use axum::{extract::{Path, State}, http::{header, HeaderMap, HeaderValue, StatusCode}, response::IntoResponse, routing::{get, post, patch, delete}, Json, Router};
use argon2::{Argon2, PasswordHash, PasswordHasher, PasswordVerifier};
use argon2::password_hash::{SaltString, rand_core::OsRng};
use gaia_space_lib::{db, platform, personal};
use rand::RngCore;
use rusqlite::params;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{env, net::SocketAddr, path::PathBuf};

#[derive(Clone)] struct App;
#[derive(Serialize)] struct User { id:String, username:String, display_name:String, profile_id:String, role:String }
#[derive(Deserialize)] struct Login { username:String, password:String }
#[derive(Deserialize)] struct Password { current:String, next:String }
#[derive(Deserialize)] struct CreateUser { username:String, password:String, display_name:String, role:String, profile_id:Option<String> }
#[derive(Deserialize)] struct PatchUser { display_name:Option<String>, role:Option<String>, active:Option<bool>, password:Option<String> }
fn err(code:StatusCode, s:&str)->(StatusCode,Json<Value>){(code,Json(json!({"ok":false,"error":s})))}
fn hash(password:&str)->Result<String,String>{ let salt=SaltString::generate(&mut OsRng); Argon2::default().hash_password(password.as_bytes(),&salt).map(|x|x.to_string()).map_err(|e|e.to_string()) }
fn token()->String { let mut b=[0u8;32]; rand::thread_rng().fill_bytes(&mut b); hex::encode(b) }
fn user_by_token(headers:&HeaderMap)->Result<User, (StatusCode,Json<Value>)> { let t=headers.get(header::COOKIE).and_then(|v|v.to_str().ok()).and_then(|s|s.split(';').find_map(|x|x.trim().strip_prefix("space_session="))).ok_or_else(||err(StatusCode::UNAUTHORIZED,"unauthorized"))?; let c=db::conn().map_err(|e|err(StatusCode::INTERNAL_SERVER_ERROR,&e))?; c.query_row("SELECT u.id,u.username,u.display_name,u.profile_id,u.role FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=?1 AND s.expires_at>unixepoch() AND u.active=1",[t],|r|Ok(User{id:r.get(0)?,username:r.get(1)?,display_name:r.get(2)?,profile_id:r.get(3)?,role:r.get(4)?})).map_err(|_|err(StatusCode::UNAUTHORIZED,"unauthorized")) }
fn admin(h:&HeaderMap)->Result<User,(StatusCode,Json<Value>)>{let u=user_by_token(h)?;if u.role=="admin" {Ok(u)}else{Err(err(StatusCode::FORBIDDEN,"admin required"))}}
async fn login(Json(x):Json<Login>)->impl IntoResponse { let c=match db::conn(){Ok(x)=>x,Err(e)=>return err(StatusCode::INTERNAL_SERVER_ERROR,&e).into_response()}; let row=c.query_row("SELECT id,username,password_hash,display_name,profile_id,role FROM users WHERE username=?1 AND active=1",[&x.username],|r|Ok((r.get::<_,String>(0)?,r.get(1)?,r.get::<_,String>(2)?,r.get(3)?,r.get(4)?,r.get(5)?))); let Ok((id,username,ph,display_name,profile_id,role))=row else { return err(StatusCode::UNAUTHORIZED,"invalid username or password").into_response() }; let ok=PasswordHash::new(&ph).ok().and_then(|p|Argon2::default().verify_password(x.password.as_bytes(),&p).ok()).is_some(); if !ok{return err(StatusCode::UNAUTHORIZED,"invalid username or password").into_response()} let t=token(); let _=c.execute("INSERT INTO sessions(token,user_id,created_at,expires_at) VALUES(?1,?2,unixepoch(),unixepoch()+2592000)",params![t,id]); let mut resp=Json(json!({"user":User{id,username,display_name,profile_id,role}})).into_response(); resp.headers_mut().insert(header::SET_COOKIE,HeaderValue::from_str(&format!("space_session={t}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=2592000")).unwrap());resp }
async fn me(h:HeaderMap)->impl IntoResponse{match user_by_token(&h){Ok(u)=>Json(json!({"user":u})).into_response(),Err(e)=>e.into_response()}}
async fn logout(h:HeaderMap)->impl IntoResponse{if let Some(t)=h.get(header::COOKIE).and_then(|v|v.to_str().ok()).and_then(|s|s.split(';').find_map(|x|x.trim().strip_prefix("space_session="))){if let Ok(c)=db::conn(){let _=c.execute("DELETE FROM sessions WHERE token=?1",[t]);}}let mut r=Json(json!({"ok":true})).into_response();r.headers_mut().insert(header::SET_COOKIE,HeaderValue::from_static("space_session=; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=0"));r}
async fn change_password(h:HeaderMap,Json(x):Json<Password>)->impl IntoResponse{let u=match user_by_token(&h){Ok(u)=>u,Err(e)=>return e.into_response()};let c=db::conn().unwrap();let ph:String=c.query_row("SELECT password_hash FROM users WHERE id=?1",[&u.id],|r|r.get(0)).unwrap();if PasswordHash::new(&ph).ok().and_then(|p|Argon2::default().verify_password(x.current.as_bytes(),&p).ok()).is_none(){return err(StatusCode::UNAUTHORIZED,"invalid username or password").into_response()}let p=hash(&x.next).unwrap();let _=c.execute("UPDATE users SET password_hash=?1 WHERE id=?2",params![p,u.id]);let _=c.execute("DELETE FROM sessions WHERE user_id=?1",[&u.id]);Json(json!({"ok":true})).into_response()}
async fn users(h:HeaderMap)->impl IntoResponse{if let Err(e)=admin(&h){return e.into_response()}let c=db::conn().unwrap();let mut q=c.prepare("SELECT id,username,display_name,profile_id,role FROM users ORDER BY username").unwrap();let v:Vec<User>=q.query_map([],|r|Ok(User{id:r.get(0)?,username:r.get(1)?,display_name:r.get(2)?,profile_id:r.get(3)?,role:r.get(4)?})).unwrap().filter_map(Result::ok).collect();Json(v).into_response()}
async fn create_user(h:HeaderMap,Json(x):Json<CreateUser>)->impl IntoResponse{if let Err(e)=admin(&h){return e.into_response()}if !matches!(x.role.as_str(),"admin"|"member"){return err(StatusCode::BAD_REQUEST,"invalid role").into_response()}let c=db::conn().unwrap();let id=token();let pid=x.profile_id.unwrap_or_else(||format!("profile-{}",&id[..12]));let _=c.execute("INSERT OR IGNORE INTO profiles(id,username,display_name,created_at) VALUES(?1,?2,?3,unixepoch())",params![pid,x.username,x.display_name]);match c.execute("INSERT INTO users(id,username,password_hash,display_name,profile_id,role,created_at) VALUES(?1,?2,?3,?4,?5,?6,unixepoch())",params![id,x.username,hash(&x.password).unwrap(),x.display_name,pid,x.role]){Ok(_)=>Json(json!({"id":id})).into_response(),Err(e)=>err(StatusCode::BAD_REQUEST,&e.to_string()).into_response()}}
async fn delete_user(h:HeaderMap,Path(id):Path<String>)->impl IntoResponse{let me=match admin(&h){Ok(u)=>u,Err(e)=>return e.into_response()};if id==me.id{return err(StatusCode::BAD_REQUEST,"cannot delete yourself").into_response()}let c=db::conn().unwrap();let n:i64=c.query_row("SELECT count(*) FROM users WHERE role='admin' AND active=1",[],|r|r.get(0)).unwrap();let target:String=c.query_row("SELECT role FROM users WHERE id=?1",[&id],|r|r.get(0)).unwrap_or_default();if target=="admin"&&n<=1{return err(StatusCode::BAD_REQUEST,"cannot delete last active admin").into_response()}let _=c.execute("DELETE FROM users WHERE id=?1",[id]);Json(json!({"ok":true})).into_response()}
async fn patch_user(h:HeaderMap,Path(id):Path<String>,Json(x):Json<PatchUser>)->impl IntoResponse{if let Err(e)=admin(&h){return e.into_response()}let c=db::conn().unwrap();if let Some(v)=x.display_name{let _=c.execute("UPDATE users SET display_name=?1 WHERE id=?2",params![v,id]);}if let Some(v)=x.role{let _=c.execute("UPDATE users SET role=?1 WHERE id=?2",params![v,id]);}if let Some(v)=x.active{let _=c.execute("UPDATE users SET active=?1 WHERE id=?2",params![v as i32,id]);}if let Some(v)=x.password{let _=c.execute("UPDATE users SET password_hash=?1 WHERE id=?2",params![hash(&v).unwrap(),id]);}Json(json!({"ok":true})).into_response()}
async fn cmd(h:HeaderMap,Path(name):Path<String>,Json(body):Json<Value>)->impl IntoResponse{if let Err(e)=user_by_token(&h){return e.into_response()}match name.as_str(){"list_profiles"=>match platform::list_profiles(){Ok(v)=>Json(json!({"ok":true,"value":v})).into_response(),Err(e)=>err(StatusCode::BAD_REQUEST,&e).into_response()},"create_todo"=>{let profile=body.get("profile_id").or_else(||body.get("profileId")).and_then(Value::as_str).unwrap_or("default-org").to_string();let content=body.get("content").and_then(Value::as_str).unwrap_or("").to_string();match personal::create_todo(personal::TodoInput{id:None,profile_id:profile,content,due_date:None,done:false,source_entity_type:None,source_entity_id:None}){Ok(v)=>Json(json!({"ok":true,"value":v})).into_response(),Err(e)=>err(StatusCode::BAD_REQUEST,&e).into_response()}},n if n.starts_with("repo_")=>err(StatusCode::NOT_IMPLEMENTED,"not available in web mode").into_response(),_=>err(StatusCode::NOT_FOUND,"unknown command").into_response()}}
fn bootstrap(){let c=db::conn().expect("database");db::seed(&c).expect("seed");let n:i64=c.query_row("SELECT count(*) FROM users",[],|r|r.get(0)).unwrap();if n==0{let pw=env::var("SPACE_ADMIN_PASSWORD").unwrap_or_else(|_|{let p=token();println!("SPACE_ADMIN_PASSWORD={p}");p});c.execute("INSERT INTO users(id,username,password_hash,display_name,profile_id,role,created_at) VALUES('admin','admin',?1,'Administrator','default-org','admin',unixepoch())",[hash(&pw).unwrap()]).unwrap();}}
#[tokio::main] async fn main(){let p=env::var("SPACE_DB").unwrap_or_else(|_|"/var/lib/gaia-space/space.db".into());db::set_db_path(PathBuf::from(p));bootstrap();let app=Router::new().route("/api/auth/login",post(login)).route("/api/auth/logout",post(logout)).route("/api/auth/me",get(me)).route("/api/auth/password",post(change_password)).route("/api/users",get(users).post(create_user)).route("/api/users/:id",patch(patch_user).delete(delete_user)).route("/api/cmd/:command",post(cmd)).with_state(App);let port=env::var("SPACE_PORT").ok().and_then(|x|x.parse().ok()).unwrap_or(8090);axum::serve(tokio::net::TcpListener::bind(SocketAddr::from(([127,0,0,1],port))).await.unwrap(),app).await.unwrap();}
